INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('0615a0ef-50c5-5aa9-a795-539bb8192624'::uuid, '84605358-5dd4-5dec-898e-0f7e477af767'::uuid, 'Des projets d’envergure au Maroc', 'Depuis des années, Kayne Étanchéité Isolation intervient sur des projets variés et prestigieux, allant des bâtiments institutionnels comme le Ministère de l’Équipement et le Parlement, aux infrastructures portuaires de l’ANP, en passant par des complexes résidentiels et hôteliers tels que l’Hôtel St Regis et les projets du Groupe Eagle Hills. Nous accompagnons également des partenaires industriels', '["https://kayne-etancheite.com/wp-content/uploads/2022/01/Photos-chantiers-enduit-de-cuvelage-1.jpg"]'::jsonb, 'https://kayne-etancheite.com/wp-content/uploads/2022/01/Photos-chantiers-enduit-de-cuvelage-1.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.7' LIMIT 1));
